// Collect all data and format improved report
const summary = $('Get Dashboard Summary').first().json.data || {};
const weather = $('Get Weather').first().json.data || {};
const incidentsData = $('Get Today's Incidents').first().json.data || [];

const today = new Date();
const dateStr = today.toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
const timeStr = today.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true });

// Calculate task completion rate
const totalTasks = summary.pendingTasks + summary.completedTasks;
const completionRate = totalTasks > 0 ? Math.round((summary.completedTasks / totalTasks) * 100) : 0;

// Create progress bar
const progressLength = Math.floor(completionRate / 10);
const progressBar = '█'.repeat(progressLength) + '░'.repeat(10 - progressLength);

// Weather summary
const todayForecast = weather.forecast?.[0] || {};
const tomorrowForecast = weather.forecast?.[1] || {};
const todayRain = todayForecast.rainfallMm || 0;
const tomorrowRain = tomorrowForecast.rainfallMm || 0;
const rainTomorrow = tomorrowRain > 0 ? 'Yes' : 'No';
const rainAmount = tomorrowRain > 0 ? ` (${tomorrowRain.toFixed(1)}mm)` : '';

// Count incidents by severity
const criticalIncidents = incidentsData.filter(i => i.severity === 'CRITICAL').length;
const highIncidents = incidentsData.filter(i => i.severity === 'NORMAL').length;
const mediumIncidents = incidentsData.filter(i => i.severity === 'WARNING').length;

// Format message with improved structure
let message = `📊 <b>Daily Farm Summary</b>\n`;
message += `━━━━━━━━━━━━━━━━━━━━━━\n`;
message += `📅 ${dateStr}\n`;
message += `⏰ Report Time: ${timeStr}\n\n`;

message += `🌾 <b>Task Completion</b>\n`;
message += `━━━━━━━━━━━━━━━━━━━━━━\n`;
message += `${progressBar} ${completionRate}%\n\n`;
message += `✅ Completed: ${summary.completedTasks || 0}\n`;
message += `⏳ Pending: ${summary.pendingTasks || 0}\n`;
message += `📊 Total: ${totalTasks}\n\n`;

message += `🌧️ <b>Weather Forecast</b>\n`;
message += `━━━━━━━━━━━━━━━━━━━━━━\n`;
message += `📍 ${weather.location || 'Addis Ababa'}\n`;
message += `🌡️ Current: ${todayForecast.temperatureMax || '--'}°C\n`;
message += `💧 Today's Rain: ${todayRain.toFixed(1)}mm\n`;
message += `🌧️ Rain Tomorrow: ${rainTomorrow}${rainAmount}\n`;
if (weather.recommendation) {
  message += `💡 ${weather.recommendation}\n`;
}
message += `\n`;

message += `🦠 <b>Incidents Overview</b>\n`;
message += `━━━━━━━━━━━━━━━━━━━━━━\n`;
message += `⚠️ Open: ${summary.openIncidents || 0}\n`;
message += `📋 Total Today: ${incidentsData.length}\n`;
if (incidentsData.length > 0) {
  message += `\n<b>By Severity:</b>\n`;
  message += `🔴 Critical: ${criticalIncidents}\n`;
  message += `🟠 High: ${highIncidents}\n`;
  message += `🟡 Medium: ${mediumIncidents}\n`;
}
message += `\n`;

message += `📍 <b>Fields Status</b>\n`;
message += `━━━━━━━━━━━━━━━━━━━━━━\n`;
message += `🌱 Total Fields: ${summary.totalFields || 0}\n`;
message += `\n`;

message += `━━━━━━━━━━━━━━━━━━━━━━\n\n`;

// Add insights/recommendations
message += `<b>📈 Key Insights:</b>\n`;
if (completionRate >= 80) {
  message += `✅ Excellent task completion rate!\n`;
} else if (completionRate >= 50) {
  message += `👍 Good progress. Keep it up!\n`;
} else {
  message += `⚠️ Task completion needs attention.\n`;
}

if (tomorrowRain > 15) {
  message += `🌧️ Heavy rain expected - adjust irrigation schedule.\n`;
}

if (criticalIncidents > 0) {
  message += `🚨 ${criticalIncidents} critical incident(s) require immediate action.\n`;
}

message += `\n`;
message += `<i>Generated by EthioSugar Automation</i>`;

return [{
  json: {
    message,
    completionRate,
    totalTasks,
    totalIncidents: incidentsData.length,
    criticalIncidents,
    date: dateStr,
    time: timeStr
  }
}];

// Error handler with detailed context
const error = $input.first().json.error || {};
const timestamp = new Date().toLocaleString('en-US', { 
  timeZone: 'Africa/Addis_Ababa',
  dateStyle: 'medium',
  timeStyle: 'short'
});

return {
  json: {
    errorMessage: error.message || error.code || 'Report generation failed',
    errorDetails: JSON.stringify(error, null, 2),
    workflow: 'Daily Summary Report',
    timestamp: timestamp,
    severity: 'WARNING'
  }
};
